+import type { ReactNode } from "react";
+import "./upgrade-button.css";
+
+export function UpgradeButton({ highlighted, onClick, children }: { highlighted: boolean; onClick: () => void; children: ReactNode }) {
+  return (
+    <button type="button" className={highlighted ? "upgrade-button upgrade-button--hot" : "upgrade-button"} onClick={onClick}>
+      {children}
+    </button>
+  );
+}
